 if(!displayed.length){const empty=el('div',undefined,'empty-list');empty.append(el('p',runs.length?'No runs match these filters.':'Your library is ready for its first run.'));if(runs.length)empty.append(button('Clear filters',()=>$('clear-filters').click()));else empty.append(el('p','Choose New test to set up and run your first backtest from Vault.'));list.append(empty);}
