async function refresh(){[runs,benchmarks]=await Promise.all([S.all(),S.allBenchmarks?.()||Promise.resolve([])]);const old=$('cohort').value;$('cohort').replaceChildren(new Option('All periods & universes',''));[...new Set(runs.map(cohort))].sort().forEach(c=>$('cohort').add(new Option(c,c)));$('cohort').value=[...$('cohort').options].some(o=>o.value===old)?old:'';renderList();}
for(const id of ['search','cohort','sort','risk'])$(id).addEventListener('input',renderList);
