if(S.demo){document.querySelector('.brand').href='?demo=1';$('demo-banner').hidden=false;$('mode-label').textContent='Demo mode';$('mode-label').classList.add('demo');$('demo-link').textContent='Open my archive';$('demo-link').href='index.html';$('import-trigger').disabled=true;$('import-trigger').title='Open your local archive to import a backup.';note('');}
