$('summary').onclick=()=>{const list=selectedSet.size>=2?runs.filter(r=>selectedSet.has(r.id)):filtered(),maps=list.map(P.parameterMap),keys=[...new Set(maps.flatMap(m=>[...m.keys()]))];const headers=['Run ID','Run name','Saved at','Group','From','To','Timeframe','Gross return (%)','Max drawdown (%)','CAGR / annualized return (%)','Return measure','CAGR (%)','Annualized return (%)','Reported trades','Captured trades','Win ratio (%)','Initial capital','Final capital','Settings provenance','Capture warnings','Notes',...keys.map(k=>maps.find(m=>m.has(k)).get(k).label)];const fixed=n=>n===null?'':n.toFixed(2);const rows=list.map((r,i)=>{const d=V.details(r),m=V.metrics(r);return [r.id,r.name,r.savedAt,d.group,d.from,d.to,d.timeframe,fixed(m.returns),fixed(m.drawdown),fixed(m.growth),m.growth===null?'':m.growthLabel,fixed(m.cagr),fixed(m.annualized),m.trades,r.trades.rows.length,fixed(m.win),fixed(m.capital),fixed(m.final),r.provenance,V.assessment(r).join('; '),r.notes,...keys.map(k=>maps[i].get(k)?.text||'')];});download('backtest-comparison.csv',V.csv([headers,...rows]),'text/csv;charset=utf-8');};
$('import').onchange=async event=>{if(S.demo){note('Open your local archive to import a backup.');event.target.value='';return;}try {const staged=[],stagedBenchmarks=[],stagedExperiments=[];for(const file of event.target.files){if(file.size>100*1024*1024)throw new Error('Import files must be smaller than 100 MB.');const data=JSON.parse(await file.text());if(data.experiments!==undefined){if(!Array.isArray(data.experiments)||!window.VaultExperiments)throw Error('Invalid experiment collection.');for(const e of data.experiments)stagedExperiments.push(window.VaultExperiments.restored(e));}if(data.benchmarks!==undefined){if(!Array.isArray(data.benchmarks))throw new Error('Invalid benchmark collection.');for(const b of data.benchmarks){if(!window.VaultIntelligence)throw new Error('Benchmark validation is unavailable.');window.VaultIntelligence.validateBenchmark(b);stagedBenchmarks.push(b);}}const incoming=Array.isArray(data.runs)?data.runs:[data];for(const r of incoming){V.validate(r);r.charts=r.charts.map(c=>({...c,svg:V.safeSvg(c.svg)}));staged.push(r);}}const ids=new Set(runs.map(r=>r.id));let added=0;for(const r of staged){if(ids.has(r.id))continue;await S.put(r);ids.add(r.id);added++;}const benchmarkIds=new Set(benchmarks.map(b=>b.id));let benchmarkAdded=0;for(const b of stagedBenchmarks){if(benchmarkIds.has(b.id))continue;await S.putBenchmark(b);benchmarkIds.add(b.id);benchmarkAdded++;}const experimentIds=new Set((await S.allExperiments?.()||[]).map(e=>e.id));for(const e of stagedExperiments){if(experimentIds.has(e.id))continue;await S.putExperiment(e);experimentIds.add(e.id);}await refresh();if(added&&!selectedId&&runs.length)openRun(filtered()[0]);note(`Imported ${added} runs and ${benchmarkAdded} benchmarks. Existing IDs were kept unchanged.`);}catch(e){await refresh();note(`Import stopped: ${e.message}`,true);}finally{event.target.value='';}};
window.addEventListener('focus',()=>refresh().catch(e=>note(e.message,true)));
refresh().then(()=>{if(new URLSearchParams(location.search).get('view')==='experiments'){showExperiments();return;}if(new URLSearchParams(location.search).get('view')==='analysis'){showIntelligence();return;}if(runs.length){const first=filtered()[0];selectedId=first.id;renderList();renderRun(first);}}).catch(e=>note(`Local storage could not be opened: ${e.message}`,true));
async function showIntelligence(chosen){window.VaultExperimentsUI?.dispose();try{await refresh();document.body.classList.add('analysis-mode');revokeCharts();isComparing=false;const scope=chosen||runs;window.VaultIntelligenceUI.render({target:$('detail'),runs:scope,benchmarks,store:S,table,preferences:await S.getTablePreferences?.(),onOpen:r=>openRun(r,true),onExit:()=>{if(runs.length)openRun(runs.find(r=>r.id===selectedId)||runs[0],true);else {document.body.classList.remove('analysis-mode');location.href='index.html';}},onNotice:note,onBenchmarksChanged:refresh,download});$('detail').focus({preventScroll:true});$('detail').scrollIntoView({block:'start'});}catch(e){note('Analysis could not be opened: '+e.message,true);}}
$('analyze').onclick=()=>showIntelligence();

async function showExperiments(baselineRun,startNew=false){try{await refresh();document.body.classList.add('analysis-mode');revokeCharts();isComparing=false;await window.VaultExperimentsUI.render({target:$('detail'),store:S,runs,onOpen:r=>openRun(r,true),onExit:()=>{window.VaultExperimentsUI.dispose();document.body.classList.remove('analysis-mode');if(runs.length)openRun(runs[0]);else location.href=S.demo?'?demo=1':'index.html';},onNotice:note,table,download,baselineRun,startNew});$('detail').focus({preventScroll:true});$('detail').scrollIntoView({block:'start'});}catch(e){note('Experiments could not be opened: '+e.message,true);}}
if($('experiments'))$('experiments').onclick=()=>showExperiments();
if($('new-test'))$('new-test').onclick=()=>showExperiments(null,true);
if($('empty-new-test'))$('empty-new-test').onclick=()=>showExperiments(null,true);
